1	import { Schema } from "effect";
2	import { TeamId } from "../people/Team.ts";
3	import { QuestionType, QuestionVersionId } from "../pulses/Question.ts";
4	import { enforceEffectiveNOnResult, type QuestionInput, type RoundResult } from "./Results.ts";
5	import { RoundId, type RoundStatus } from "./Round.ts";
6	
7	/**
8	 * One Question of a Round in the member's history. `teamScore` is the Team's score for it, only when
9	 * the Round is shown and the Question is a Rating that meets the minimum group size (ADR 0004).
10	 */
11	export const HistoryQuestion = Schema.Struct({
12	  questionVersionId: QuestionVersionId,
13	  position: Schema.Int,
14	  text: Schema.String,
15	  type: QuestionType,
16	  teamScore: Schema.NullOr(Schema.Finite),
17	});
18	export type HistoryQuestion = typeof HistoryQuestion.Type;
19	
20	/**
21	 * Why a Round's Team scores are or are not shown: not shared (or not visible to the member), below
22	 * the minimum group size, or shown.
23	 */
24	export const HistoryTeamResult = Schema.Literals(["shown", "notShared", "belowMinimumGroupSize"]);
25	export type HistoryTeamResult = typeof HistoryTeamResult.Type;
26	
27	/** One Round the signed-in Person took part in. Carries no Submission data (ADR 0017). */
28	export const HistoryRound = Schema.Struct({
29	  roundId: RoundId,
30	  teamId: TeamId,
31	  teamName: Schema.String,
32	  pulseName: Schema.String,
33	  plannedOpenDate: Schema.String,
34	  teamResult: HistoryTeamResult,
35	  questions: Schema.Array(HistoryQuestion),
36	});
37	export type HistoryRound = typeof HistoryRound.Type;
38	
39	/** The signed-in Person's Rounds, newest first. */
40	export const MemberHistory = Schema.Struct({
41	  rounds: Schema.Array(HistoryRound),
42	});
43	export type MemberHistory = typeof MemberHistory.Type;
44	
45	/** What the history needs about one Round the Person took part in. */
46	export interface MemberHistoryRoundInput {
47	  readonly roundId: RoundId;
48	  readonly teamId: TeamId;
49	  readonly teamName: string;
50	  readonly pulseName: string;
51	  readonly plannedOpenDate: string;
52	  readonly status: RoundStatus;
53	  readonly questions: ReadonlyArray<QuestionInput>;
54	  readonly result: RoundResult | null;
55	  readonly canViewResults: boolean;
56	}
57	
58	const compareStrings = (a: string, b: string): number => (a < b ? -1 : a > b ? 1 : 0);
59	
60	const historyRound = (input: MemberHistoryRoundInput, minimumGroupSize: number): HistoryRound => {
61	  const questions = [...input.questions].sort((a, b) => a.position - b.position);
62	  const base = {
63	    roundId: input.roundId,
64	    teamId: input.teamId,
65	    teamName: input.teamName,
66	    pulseName: input.pulseName,
67	    plannedOpenDate: input.plannedOpenDate,
68	  };
69	  const noScores = (teamResult: HistoryTeamResult): HistoryRound => ({
70	    ...base,
71	    teamResult,
72	    questions: questions.map((question) => toHistoryQuestion(question, null)),
73	  });
74	
75	  // The Round's own status decides, not the stored payload, which can lag behind sharing.
76	  if (input.status !== "shared" || !input.canViewResults || input.result === null) {
77	    return noScores("notShared");
78	  }
79	
80	  const enforced = enforceEffectiveNOnResult(input.result, minimumGroupSize);
81	  if (!enforced.meetsMinimumGroupSize) return noScores("belowMinimumGroupSize");
82	
83	  return {
84	    ...base,
85	    teamResult: "shown",
86	    questions: questions.map((question) => {
87	      const result = enforced.questions.find((each) => each.questionVersionId === question.id);
88	      const score =
89	        question.type._tag === "Rating" && result !== undefined && result.meetsMinimumGroupSize
90	          ? result.score
91	          : null;
92	      return toHistoryQuestion(question, score);
93	    }),
94	  };
95	};
96	
97	const toHistoryQuestion = (question: QuestionInput, teamScore: number | null): HistoryQuestion => ({
98	  questionVersionId: question.id,
99	  position: question.position,
100	  text: question.text,
101	  type: question.type,
102	  teamScore,
103	});
104	
105	/**
106	 * Builds the signed-in Person's history. Each Round's Team scores follow the same rules as the
107	 * Round's Result: shown only when shared, visible to the member, and at least N under the stricter
108	 * of the stored and the current minimum group size (ADR 0004, ADR 0017).
109	 */
110	export const buildMemberHistory = (params: {
111	  readonly rounds: ReadonlyArray<MemberHistoryRoundInput>;
112	  readonly minimumGroupSize: number;
113	}): MemberHistory => {
114	  const rounds = params.rounds
115	    .map((round) => historyRound(round, params.minimumGroupSize))
116	    .sort(
117	      (a, b) => compareStrings(b.plannedOpenDate, a.plannedOpenDate) || compareStrings(b.roundId, a.roundId),
118	    );
119	  return { rounds };
120	};
121

1	import { PulseId, RoundId, TeamId } from "@surveybeat/domain";
2	import { pipe, Schema } from "effect";
3	import {
4	  defineRouteUnion,
5	  literal,
6	  mapTo,
7	  oneOf,
8	  parseUrlWithFallback,
9	  root,
10	  schemaSegment,
11	  slash,
12	} from "foldkit/route";
13	import type { Url } from "foldkit/url";
14	
15	export const AppRoute = defineRouteUnion({
16	  Teams: {},
17	  Team: { teamId: TeamId },
18	  Pulses: { teamId: TeamId },
19	  Pulse: { teamId: TeamId, pulseId: PulseId },
20	  Rounds: { teamId: TeamId, pulseId: PulseId },
21	  RoundResults: { teamId: TeamId, roundId: RoundId },
22	  Settings: {},
23	  Privacy: {},
24	  NotFound: { path: Schema.String },
25	});
26	export type AppRoute = typeof AppRoute.Type;
27	
28	export const teamsRouter = pipe(root, mapTo(AppRoute.Teams));
29	export const settingsRouter = pipe(literal("settings"), mapTo(AppRoute.Settings));
30	export const privacyRouter = pipe(literal("privacy"), mapTo(AppRoute.Privacy));
31	export const teamRouter = pipe(
32	  literal("teams"),
33	  slash(schemaSegment("teamId", TeamId)),
34	  mapTo(AppRoute.Team),
35	);
36	export const pulsesRouter = pipe(
37	  literal("teams"),
38	  slash(schemaSegment("teamId", TeamId)),
39	  slash(literal("pulses")),
40	  mapTo(AppRoute.Pulses),
41	);
42	export const pulseRouter = pipe(
43	  literal("teams"),
44	  slash(schemaSegment("teamId", TeamId)),
45	  slash(literal("pulses")),
46	  slash(schemaSegment("pulseId", PulseId)),
47	  mapTo(AppRoute.Pulse),
48	);
49	export const roundsRouter = pipe(
50	  literal("teams"),
51	  slash(schemaSegment("teamId", TeamId)),
52	  slash(literal("pulses")),
53	  slash(schemaSegment("pulseId", PulseId)),
54	  slash(literal("rounds")),
55	  mapTo(AppRoute.Rounds),
56	);
57	export const roundResultsRouter = pipe(
58	  literal("teams"),
59	  slash(schemaSegment("teamId", TeamId)),
60	  slash(literal("rounds")),
61	  slash(schemaSegment("roundId", RoundId)),
62	  mapTo(AppRoute.RoundResults),
63	);
64	
65	export const appRouter = oneOf(
66	  roundResultsRouter,
67	  roundsRouter,
68	  pulseRouter,
69	  pulsesRouter,
70	  teamRouter,
71	  settingsRouter,
72	  privacyRouter,
73	  teamsRouter,
74	);
75	export const urlToAppRoute = (url: Url): AppRoute => parseUrlWithFallback(appRouter, AppRoute.NotFound)(url);
76	
77	export const teamsHref = () => teamsRouter.build({});
78	export const settingsHref = () => settingsRouter.build({});
79	export const privacyHref = () => privacyRouter.build({});
80	export const teamHref = (teamId: TeamId) => teamRouter.build({ teamId });
81	export const pulsesHref = (teamId: TeamId) => pulsesRouter.build({ teamId });
82	export const pulseHref = (teamId: TeamId, pulseId: PulseId) => pulseRouter.build({ teamId, pulseId });
83	export const roundsHref = (teamId: TeamId, pulseId: PulseId) => roundsRouter.build({ teamId, pulseId });
84	export const roundResultsHref = (teamId: TeamId, roundId: RoundId) =>
85	  roundResultsRouter.build({ teamId, roundId });
