1	import { type ActionMarker, type DimensionOverview, type RoundId, TeamOverview } from "@surveybeat/domain";
2	import type { Html, HtmlBuilder } from "foldkit/html";
3	import { defineTaggedUnion } from "foldkit/schema";
4	import { formatDate, message } from "../messages/locale.ts";
5	import { Failure } from "./api.ts";
6	import { type ChartPoint, lineChart, plotPercent } from "./charts.ts";
7	import { dataTable, emptyState, panel, problemView, sectionTitle, subSectionTitle } from "./components.ts";
8	import { toggleButton } from "./results.ts";
9	import { dimensionName } from "./pulses.ts";
10	
11	export const LoadedOverview = defineTaggedUnion({
12	  Loading: {},
13	  Loaded: { overview: TeamOverview },
14	  Failed: { failure: Failure },
15	});
16	export type LoadedOverview = typeof LoadedOverview.Type;
17	
18	/** The viewBox width of the overview charts; the marker strip is positioned against the same width. */
19	const OVERVIEW_WIDTH = 720;
20	
21	const plotBox = <Message>(children: ReadonlyArray<Html>, h: HtmlBuilder<Message>): Html =>
22	  h.div([h.Class("flex flex-col gap-2 rounded-control bg-subtle p-4")], children);
23	
24	const eventGlyph = <Message>(kind: ActionMarker["kind"], h: HtmlBuilder<Message>): Html =>
25	  h.span(
26	    [
27	      h.AriaHidden(true),
28	      h.Class(
29	        kind === "committed"
30	          ? "block size-3 shrink-0 rounded-full border-2 border-brass bg-surface"
31	          : "block size-3 shrink-0 rounded-full bg-primary",
32	      ),
33	    ],
34	    [],
35	  );
36	
37	const markerText = (marker: ActionMarker): string =>
38	  message(marker.kind === "committed" ? "overview.marker.committed" : "overview.marker.done", {
39	    date: formatDate(new Date(marker.at)),
40	    title: marker.title,
41	  });
42	
43	const tooltipBaseClass =
44	  "pointer-events-none invisible absolute bottom-full z-10 mb-1 w-max max-w-xs whitespace-normal rounded-control bg-evergreen px-2 py-1 text-xs text-on-primary group-hover:visible group-focus-visible:visible group-focus:visible";
45	
46	/** Anchors the tooltip to the marker's left edge near the start of the axis, its right edge near the end, and centred otherwise. */
47	const tooltipAnchor = (x: number): string => {
48	  if (x < 0.15) return "left-0";
49	  if (x > 0.85) return "right-0";
50	  return "left-1/2 -translate-x-1/2";
51	};
52	
53	/** One Action marker: a focusable button whose title shows on hover and keyboard focus. */
54	const markerButton = <Message>(marker: ActionMarker, x: number, h: HtmlBuilder<Message>): Html => {
55	  const text = markerText(marker);
56	  return h.button(
57	    [
58	      h.Type("button"),
59	      h.AriaLabel(text),
60	      h.Class("group absolute top-1 flex size-6 -translate-x-1/2 items-center justify-center rounded-full"),
61	      h.Style({ left: plotPercent(x, OVERVIEW_WIDTH) }),
62	    ],
63	    [
64	      eventGlyph(marker.kind, h),
65	      h.span([h.Role("tooltip"), h.Class(`${tooltipBaseClass} ${tooltipAnchor(x)}`)], [text]),
66	    ],
67	  );
68	};
69	
70	export interface OverviewXs {
71	  /** x (0..1) of each shared Round on the shared time axis. */
72	  readonly rounds: ReadonlyMap<RoundId, number>;
73	  /** x (0..1) of an epoch-ms time on the same axis, clamped to the plot. */
74	  readonly markerX: (at: number) => number;
75	}
76	
77	/**
78	 * The shared time axis of the overview: the earliest and latest of every planned open date and Action
79	 * time map to 0 and 1. A single instant (one Round, no markers) sits at the middle.
80	 */
81	export const overviewXs = (overview: TeamOverview): OverviewXs => {
82	  let tMin = Number.POSITIVE_INFINITY;
83	  let tMax = Number.NEGATIVE_INFINITY;
84	  for (const round of overview.rounds) {
85	    tMin = Math.min(tMin, Date.parse(round.plannedOpenDate));
86	    tMax = Math.max(tMax, Date.parse(round.plannedOpenDate));
87	  }
88	  for (const marker of overview.markers) {
89	    tMin = Math.min(tMin, marker.at);
90	    tMax = Math.max(tMax, marker.at);
91	  }
92	  const markerX = (at: number): number => {
93	    if (tMax === tMin) return 0.5;
94	    return Math.min(1, Math.max(0, (at - tMin) / (tMax - tMin)));
95	  };
96	  const rounds = new Map<RoundId, number>();
97	  for (const round of overview.rounds) {
98	    rounds.set(round.roundId, markerX(Date.parse(round.plannedOpenDate)));
99	  }
100	  return { rounds, markerX };
101	};
102	
103	const legend = <Message>(h: HtmlBuilder<Message>): Html =>
104	  h.p(
105	    [h.Class("flex flex-wrap items-center gap-4 text-[13px] text-muted")],
106	    [
107	      h.span(
108	        [h.Class("flex items-center gap-2")],
109	        [eventGlyph("committed", h), message("overview.legend.committed")],
110	      ),
111	      h.span([h.Class("flex items-center gap-2")], [eventGlyph("done", h), message("overview.legend.done")]),
112	    ],
113	  );
114	
115	/** One line per Dimension; the Round x positions are shared, so each Dimension reuses them. */
116	const dimensionPanel = <Message>(
117	  dimension: DimensionOverview,
118	  xByRound: ReadonlyMap<RoundId, number>,
119	  guides: ReadonlyArray<number>,
120	  h: HtmlBuilder<Message>,
121	): Html => {
122	  const name = dimensionName(dimension.dimension);
123	  const points: Array<ChartPoint> = [];
124	  for (const point of dimension.points) {
125	    const x = xByRound.get(point.roundId);
126	    if (x !== undefined) points.push({ x, score: point.score, joinsPrevious: true });
127	  }
128	  return panel(
129	    [
130	      subSectionTitle(name, h),
131	      plotBox(
132	        [
133	          lineChart(
134	            {
135	              points,
136	              ariaLabel: message("overview.chartLabel", { dimension: name }),
137	              width: OVERVIEW_WIDTH,
138	              dotRadius: 2.5,
139	              className: "block h-auto w-full",
140	              guides,
141	            },
142	            h,
143	          ),
144	        ],
145	        h,
146	      ),
147	    ],
148	    h,
149	    "flex flex-col gap-2",
150	  );
151	};
152	
153	/** Table view: one row per shared Round, one column per Dimension; a gap reads as "Too few answers". */
154	const roundsTable = <Message>(overview: TeamOverview, h: HtmlBuilder<Message>): Html => {
155	  const scoresByDimension = overview.dimensions.map(
156	    (dimension) =>
157	      new Map<string, number | null>(
158	        dimension.points.map((point): readonly [string, number | null] => [point.roundId, point.score]),
159	      ),
160	  );
161	  return dataTable(
162	    [message("overview.tableRoundDate"), ...overview.dimensions.map((d) => dimensionName(d.dimension))],
163	    overview.rounds.map((round) => [
164	      round.plannedOpenDate,
165	      ...scoresByDimension.map((scores) => {
166	        const score = scores.get(round.roundId) ?? null;
167	        return score !== null ? String(score) : message("overview.gap");
168	      }),
169	    ]),
170	    h,
171	  );
172	};
173	
174	const markersTable = <Message>(markers: ReadonlyArray<ActionMarker>, h: HtmlBuilder<Message>): Html =>
175	  dataTable(
176	    [message("overview.tableDate"), message("overview.tableAction"), message("overview.tableEvent")],
177	    markers.map((marker) => [
178	      formatDate(new Date(marker.at)),
179	      marker.title,
180	      message(marker.kind === "committed" ? "overview.event.committed" : "overview.event.done"),
181	    ]),
182	    h,
183	  );
184	
185	/** The Team health overview on the Team page: Dimension trend lines with Action markers, or tables. */
186	export const teamOverviewView = <Message>(
187	  state: LoadedOverview,
188	  isTable: boolean,
189	  onToggleTable: Message,
190	  h: HtmlBuilder<Message>,
191	): Html => {
192	  if (state._tag === "Loading") {
193	    return h.p([h.Class("text-muted")], [message("overview.loading")]);
194	  }
195	
196	  if (state._tag === "Failed") {
197	    // Organization admins outside the Team are refused; the page then simply shows no overview.
198	    if (state.failure === "Forbidden") return null;
199	    return problemView(state.failure, h);
200	  }
201	
202	  const { overview } = state;
203	  if (overview.rounds.length === 0) {
204	    return h.section(
205	      [h.Class("flex flex-col gap-4")],
206	      [sectionTitle(message("overview.title"), h), emptyState(message("overview.empty"), h)],
207	    );
208	  }
209	
210	  const { rounds: xByRound, markerX } = overviewXs(overview);
211	  const markerXs = overview.markers.map((marker) => markerX(marker.at));
212	
213	  const children: Array<Html> = [
214	    sectionTitle(message("overview.title"), h),
215	    h.p([h.Class("text-muted")], [message("overview.intro")]),
216	    h.div([h.Class("flex justify-end")], [toggleButton(isTable, onToggleTable, h)]),
217	  ];
218	
219	  if (isTable) {
220	    children.push(plotBox([roundsTable(overview, h)], h));
221	    if (overview.markers.length > 0) {
222	      children.push(plotBox([markersTable(overview.markers, h)], h));
223	    }
224	  } else {
225	    if (overview.markers.length > 0) {
226	      children.push(
227	        panel(
228	          [
229	            plotBox(
230	              [
231	                h.div(
232	                  [
233	                    h.Role("group"),
234	                    h.AriaLabel(message("overview.markersLabel")),
235	                    h.Class("relative h-8 w-full"),
236	                  ],
237	                  overview.markers.map((marker, i) => markerButton(marker, markerXs[i] ?? 0.5, h)),
238	                ),
239	                legend(h),
240	              ],
241	              h,
242	            ),
243	          ],
244	          h,
245	          "flex flex-col gap-2",
246	        ),
247	      );
248	    }
249	    for (const dimension of overview.dimensions) {
250	      children.push(dimensionPanel(dimension, xByRound, markerXs, h));
251	    }
252	  }
253	
254	  return h.section([h.Class("flex flex-col gap-4")], children);
255	};
