75	
76	export const shellView = <Message>(
77	  title: string,
78	  organizationAdmin: boolean,
79	  children: ReadonlyArray<Child>,
80	  language: LanguageChoice<Message>,
81	  h: HtmlBuilder<Message>,
82	  wide = false,
