1	export const keptAnswersPrefix = "sb_answers_";
2	export const keptAnswersLifetimeMs = 365 * 24 * 60 * 60 * 1000;
3	export interface KeptAnswer {
4	  readonly value?: number;
5	  readonly comment?: string;
6	}
7	
8	const readAnswers = (raw: string | null): Record<string, unknown> => {
9	  let data: unknown;
10	  try {
11	    data = JSON.parse(raw ?? "null");
12	  } catch {
13	    return {};
14	  }
15	  if (typeof data !== "object" || data === null || !("answers" in data)) return {};
16	  const { answers } = data;
17	  return typeof answers === "object" && answers !== null ? { ...answers } : {};
18	};
19	
20	/** Merges one Answer into the Round's kept answers and pushes the expiry to a year from now. Never throws. */
21	export const keepAnswer = (
22	  storage: Pick<Storage, "getItem" | "setItem">,
23	  roundId: string,
24	  questionVersionId: string,
25	  answer: KeptAnswer,
26	  now: number,
27	): void => {
28	  try {
29	    const key = keptAnswersPrefix + roundId;
30	    const answers = readAnswers(storage.getItem(key));
31	    const prior = answers[questionVersionId];
32	    answers[questionVersionId] = { ...(typeof prior === "object" && prior !== null ? prior : {}), ...answer };
33	    storage.setItem(key, JSON.stringify({ expiresAt: now + keptAnswersLifetimeMs, answers }));
34	  } catch {
35	    // Storage can be unavailable (private mode, quota); answering must still work.
36	  }
37	};
