43	const tooltipBaseClass =
44	  "pointer-events-none invisible absolute bottom-full z-10 mb-1 w-max max-w-xs whitespace-normal rounded-control bg-evergreen px-2 py-1 text-xs text-on-primary group-hover:visible group-focus-visible:visible group-focus:visible";
45	
46	/** Anchors the tooltip to the marker's left edge near the start of the axis, its right edge near the end, and centred otherwise. */
47	const tooltipAnchor = (x: number): string => {
48	  if (x < 0.15) return "left-0";
49	  if (x > 0.85) return "right-0";
50	  return "left-1/2 -translate-x-1/2";
