53	/** One Action marker: a focusable button whose title shows on hover and keyboard focus. */
54	const markerButton = <Message>(marker: ActionMarker, x: number, h: HtmlBuilder<Message>): Html => {
55	  const text = markerText(marker);
56	  return h.button(
57	    [
58	      h.Type("button"),
