70	export interface OverviewXs {
71	  /** x (0..1) of each shared Round on the shared time axis. */
72	  readonly rounds: ReadonlyMap<RoundId, number>;
73	  /** x (0..1) of an epoch-ms time on the same axis, clamped to the plot. */
74	  readonly markerX: (at: number) => number;
75	}
76	
77	/**
78	 * The shared time axis of the overview: the earliest and latest of every planned open date and Action
79	 * time map to 0 and 1. A single instant (one Round, no markers) sits at the middle.
80	 */
81	export const overviewXs = (overview: TeamOverview): OverviewXs => {
82	  let tMin = Number.POSITIVE_INFINITY;
83	  let tMax = Number.NEGATIVE_INFINITY;
84	  for (const round of overview.rounds) {
85	    tMin = Math.min(tMin, Date.parse(round.plannedOpenDate));
86	    tMax = Math.max(tMax, Date.parse(round.plannedOpenDate));
87	  }
88	  for (const marker of overview.markers) {
89	    tMin = Math.min(tMin, marker.at);
90	    tMax = Math.max(tMax, marker.at);
91	  }
92	  const markerX = (at: number): number => {
93	    if (tMax === tMin) return 0.5;
94	    return Math.min(1, Math.max(0, (at - tMin) / (tMax - tMin)));
95	  };
96	  const rounds = new Map<RoundId, number>();
97	  for (const round of overview.rounds) {
98	    rounds.set(round.roundId, markerX(Date.parse(round.plannedOpenDate)));
99	  }
100	  return { rounds, markerX };
101	};
102	
103	const legend = <Message>(h: HtmlBuilder<Message>): Html =>
104	  h.p(
105	    [h.Class("flex flex-wrap items-center gap-4 text-[13px] text-muted")],
106	    [
107	      h.span(
108	        [h.Class("flex items-center gap-2")],
109	        [eventGlyph("committed", h), message("overview.legend.committed")],
110	      ),
111	      h.span([h.Class("flex items-center gap-2")], [eventGlyph("done", h), message("overview.legend.done")]),
112	    ],
113	  );
114	
115	/** One line per Dimension; the Round x positions are shared, so each Dimension reuses them. */
116	const dimensionPanel = <Message>(
117	  dimension: DimensionOverview,
118	  xByRound: ReadonlyMap<RoundId, number>,
119	  guides: ReadonlyArray<number>,
120	  h: HtmlBuilder<Message>,
121	): Html => {
122	  const name = dimensionName(dimension.dimension);
123	  const points: Array<ChartPoint> = [];
124	  for (const point of dimension.points) {
125	    const x = xByRound.get(point.roundId);
126	    if (x !== undefined) points.push({ x, score: point.score, joinsPrevious: true });
127	  }
128	  return panel(
129	    [
130	      subSectionTitle(name, h),
131	      plotBox(
132	        [
133	          lineChart(
134	            {
135	              points,
136	              ariaLabel: message("overview.chartLabel", { dimension: name }),
137	              width: OVERVIEW_WIDTH,
138	              dotRadius: 2.5,
139	              className: "block h-auto w-full",
140	              guides,
141	            },
142	            h,
143	          ),
144	        ],
145	        h,
146	      ),
147	    ],
148	    h,
149	    "flex flex-col gap-2",
150	  );
151	};
152	
153	/** Table view: one row per shared Round, one column per Dimension; a gap reads as "Too few answers". */
154	const roundsTable = <Message>(overview: TeamOverview, h: HtmlBuilder<Message>): Html => {
155	  const scoresByDimension = overview.dimensions.map(
156	    (dimension) =>
157	      new Map<string, number | null>(
158	        dimension.points.map((point): readonly [string, number | null] => [point.roundId, point.score]),
159	      ),
160	  );
161	  return dataTable(
162	    [message("overview.tableRoundDate"), ...overview.dimensions.map((d) => dimensionName(d.dimension))],
163	    overview.rounds.map((round) => [
164	      round.plannedOpenDate,
165	      ...scoresByDimension.map((scores) => {
166	        const score = scores.get(round.roundId) ?? null;
167	        return score !== null ? String(score) : message("overview.gap");
168	      }),
169	    ]),
170	    h,
171	  );
172	};
173	
174	const markersTable = <Message>(markers: ReadonlyArray<ActionMarker>, h: HtmlBuilder<Message>): Html =>
175	  dataTable(
176	    [message("overview.tableDate"), message("overview.tableAction"), message("overview.tableEvent")],
177	    markers.map((marker) => [
178	      formatDate(new Date(marker.at)),
179	      marker.title,
180	      message(marker.kind === "committed" ? "overview.event.committed" : "overview.event.done"),
181	    ]),
182	    h,
183	  );
